public long journeyToMoon(int n, int[][] pairs) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
    for (int[] p : pairs) {
        adj.get(p[0]).add(p[1]);
        adj.get(p[1]).add(p[0]);
    }
    boolean[] visited = new boolean[n];
    long total = (long) n * (n - 1) / 2;
    long sameCountry = 0;
    for (int start = 0; start < n; start++) {
        if (visited[start]) continue;
        long size = 0;
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(start);
        visited[start] = true;
        while (!stack.isEmpty()) {           // iterative DFS, no stack overflow
            int u = stack.pop();
            size++;
            for (int v : adj.get(u)) {
                if (!visited[v]) {
                    visited[v] = true;
                    stack.push(v);
                }
            }
        }
        sameCountry += size * (size - 1) / 2;
    }
    return total - sameCountry;
}

