def journey_to_moon(self, n: int, pairs: list[list[int]]) -> int:
    adj: list[list[int]] = [[] for _ in range(n)]
    for a, b in pairs:
        adj[a].append(b)
        adj[b].append(a)
    visited = [False] * n
    total = n * (n - 1) // 2
    same_country = 0
    for start in range(n):
        if visited[start]:
            continue
        size = 0
        stack = [start]                       # iterative DFS, no recursion limit
        visited[start] = True
        while stack:
            u = stack.pop()
            size += 1
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    stack.append(v)
        same_country += size * (size - 1) // 2
    return total - same_country

