public long journeyToMoon(int n, int[][] pairs) {
    int[] parent = new int[n];
    int[] rank = new int[n];
    int[] size = new int[n];
    for (int i = 0; i < n; i++) {
        parent[i] = i;
        size[i] = 1;
    }
    for (int[] p : pairs) {
        union(parent, rank, size, p[0], p[1]);
    }
    long answer = 0;
    long seen = 0;
    for (int i = 0; i < n; i++) {
        if (find(parent, i) == i) {          // i is a root → one country
            long s = size[i];
            answer += s * seen;              // pairs with all earlier astronauts
            seen += s;
        }
    }
    return answer;
}

private int find(int[] parent, int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];        // path halving, iterative
        x = parent[x];
    }
    return x;
}

private void union(int[] parent, int[] rank, int[] size, int a, int b) {
    int ra = find(parent, a), rb = find(parent, b);
    if (ra == rb) return;
    if (rank[ra] < rank[rb]) { int t = ra; ra = rb; rb = t; }
    parent[rb] = ra;
    size[ra] += size[rb];
    if (rank[ra] == rank[rb]) rank[ra]++;
}

code.python:
def journey_to_moon(self, n: int, pairs: list[list[int]]) -> int:
    parent = list(range(n))
    rank = [0] * n
    size = [1] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]      # path halving, iterative
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
        if rank[ra] == rank[rb]:
            rank[ra] += 1

    for a, b in pairs:
        union(a, b)

    answer = 0
    seen = 0
    for i in range(n):
        if find(i) == i:                       # i is a root → one country
            s = size[i]
            answer += s * seen                 # pairs with all earlier astronauts
            seen += s
    return answer

